import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';


export type MrtLivingProps = Record<string, any>;

const HouseIcon = () => (
  <svg width="100%" height="100%" viewBox="0 0 24 24" fill="currentColor">
    <path d="M12 3L2 12h3v8h14v-8h3L12 3zm0 2.83l7 7V20H5v-7.17l7-7z" />
    <path d="M10 14h4v6h-4z" />
  </svg>
);

const StationIcon = () => (
  <svg width="100%" height="100%" viewBox="0 0 24 24" fill="currentColor">
    <path d="M12 2c-4 0-8 .5-8 4v9.5C4 17.43 5.57 19 7.5 19L6 20.5v.5h2.23l2-2H14l2 2h2.23v-.5L16.5 19c1.93 0 3.5-1.57 3.5-3.5V6c0-3.5-4-4-8-4zm0 2c3.41 0 5.92.37 5.92 2H6.08c0-1.63 2.51-2 5.92-2zm5 11.5c0 .83-.67 1.5-1.5 1.5h-7c-.83 0-1.5-.67-1.5-1.5V12h10v3.5zM6 10V8h12v2H6zm2.5 5.5c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5zm7 0c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5z" />
  </svg>
);

const MrtLiving: React.FC<MrtLivingProps> = ({
  backgroundColor = "#1A1A2E",
  transparentBackground = false,
  durationInSeconds = 10,
  houseColor = "#4ECCA3",
  stationColor = "#E94560",
  pathColor = "#F39189",
  radarColor = "#E94560",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Diagram Layout Coordinates: House in center, 4 Stations surrounding
  const houseX = width * 0.5;
  const houseY = height * 0.5;

  const stations = [
    { x: width * 0.38, y: height * 0.35 },
    { x: width * 0.68, y: height * 0.32 },
    { x: width * 0.32, y: height * 0.62 },
    { x: width * 0.60, y: height * 0.68 },
  ].map((station, idx) => ({
    ...station,
    pathStartFrame: 30 + idx * 15,
    stationBaseFrame: 30 + idx * 15 + 10,
  }));

  // House Spring
  const houseSpring = spring({
    frame: frame - 20,
    fps,
    config: { damping: 12 }
  });
  const houseScale = interpolate(houseSpring, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Paths connecting House and Stations */}
      <svg width="100%" height="100%" style={{ position: 'absolute', top: 0, left: 0, zIndex: 5 }}>
        <defs>
          {stations.map((station, idx) => {
            const pathReveal = spring({
              frame: frame - station.pathStartFrame,
              fps,
              config: { damping: 20 }
            });
            return (
              <clipPath key={`clip-${idx}`} id={`path-clip-${idx}`}>
                <circle cx={houseX} cy={houseY} r={interpolate(pathReveal, [0, 1], [0, width])} />
              </clipPath>
            );
          })}
        </defs>
        {stations.map((station, idx) => (
          <path 
            key={`path-${idx}`}
            d={`M ${houseX} ${houseY} Q ${houseX} ${station.y} ${station.x} ${station.y}`}
            fill="none"
            stroke={pathColor}
            strokeWidth={8}
            strokeDasharray="20 20"
            strokeDashoffset={-(frame * 3)}
            strokeLinecap="round"
            clipPath={`url(#path-clip-${idx})`}
          />
        ))}
      </svg>

      {/* Radar Rings around Stations */}
      <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", zIndex: 4 }}>
        {stations.map((station, sIdx) => {
          return [0, 45, 90].map((delay, i) => {
            if (frame < station.stationBaseFrame) return null;
            
            const pingDuration = 135;
            const activeFrame = (frame - station.stationBaseFrame + delay) % pingDuration;
            
            const scale = interpolate(activeFrame, [0, pingDuration], [0, 2.5], { extrapolateRight: "clamp" });
            const opacity = interpolate(activeFrame, [0, pingDuration * 0.1, pingDuration], [0, 0.5, 0], { extrapolateRight: "clamp" });

            return (
              <div key={`radar-${sIdx}-${i}`} style={{
                position: 'absolute',
                left: station.x - 60,
                top: station.y - 60,
                width: 120,
                height: 120,
                borderRadius: '50%',
                border: `4px solid ${radarColor}`,
                transform: `scale(${scale})`,
                opacity,
                boxSizing: 'border-box',
                transition: 'none'
              }} />
            )
          });
        })}
      </div>

      {/* Station Nodes */}
      {stations.map((station, sIdx) => {
        const stationSpring = spring({
          frame: frame - station.stationBaseFrame,
          fps,
          config: { damping: 12 }
        });
        const stationScale = interpolate(stationSpring, [0, 1], [0, 1]);

        return (
          <div key={`station-${sIdx}`} style={{
            position: "absolute",
            left: station.x - 60,
            top: station.y - 60,
            width: 120,
            height: 120,
            backgroundColor: stationColor,
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${stationScale})`,
            boxShadow: `0 15px 35px ${stationColor}80`,
            zIndex: 10,
            color: "#fff"
          }}>
            <div style={{ width: 60, height: 60 }}>
              <StationIcon />
            </div>
          </div>
        );
      })}

      {/* House Node */}
      <div style={{
        position: "absolute",
        left: houseX - 50,
        top: houseY - 50,
        width: 100,
        height: 100,
        backgroundColor: houseColor,
        borderRadius: "50%",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transform: `scale(${houseScale})`,
        boxShadow: `0 15px 35px ${houseColor}80`,
        zIndex: 10,
        color: "#fff"
      }}>
        <div style={{ width: 50, height: 50 }}>
          <HouseIcon />
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default MrtLiving;